const TZ = 'America/Sao_Paulo';
const NUMERO_PADRAO = '120363412854461070@g.us'; // grupo DM Assessor Pessoal
const INTERVALO_MIN = 60; // insiste UMA vez, 1h depois do aviso
const INTERVALO_REMEDIO = 30; // 07/10: remédio insiste uma vez, 30 min depois
const MAX_ENVIOS = 2;     // 1º aviso + 1 insistência; depois para em silêncio (o resumo da noite mostra o que ficou sem ok)
const NL = '\n';
const passos = { diaria: { days: 1 }, semanal: { weeks: 1 }, mensal: { months: 1 } };
const agora = DateTime.now();
const grupos = {};
const silenciosos = [];
const l1 = t => String(t || '').split('\n')[0];
for (const r of $input.all().map(i => i.json)) {
  if (!r || r.id === undefined || r.id === null) continue;
  const q = DateTime.fromISO(String(r.quando));
  if (!q.isValid || q > agora) continue; // ainda não venceu
  const nome = r.autor || 'Daniel';
  const rem = r.remedio === true && !r.conta_id;
  // 08/10: intervalo e máximo por lembrete (ex.: "me lembre a cada 30 min até eu dizer que paguei"); nulo = padrão.
  const intervalo = Number(r.intervalo_min) > 0 ? Number(r.intervalo_min) : (rem ? INTERVALO_REMEDIO : INTERVALO_MIN);
  const maxEnvios = Number(r.max_envios) > 0 ? Number(r.max_envios) : MAX_ENVIOS;
  const passo = passos[r.recorrencia];
  let proxima = r.proxima ? DateTime.fromISO(String(r.proxima)) : null;
  if (passo && (!proxima || !proxima.isValid || proxima <= agora)) {
    proxima = q;
    while (proxima <= agora) proxima = proxima.plus(passo);
  }
  const ins = Number(r.insistencias) || 0;
  const prox = proxima ? proxima.toUTC().toISO() : null;
  let tipo, status, quando, insistencias;
  if (r.status === 'aguardando') {
    if (ins >= maxEnvios) {
      // desiste sem mandar mensagem nova (evita empilhar avisos na tela); remédio fica registrado como "sem resposta"
      const s = { id: r.id, status: passo ? 'pendente' : 'expirado', quando: (passo ? proxima : q).toUTC().toISO(), insistencias: 0, proxima: prox };
      if (rem) s.desfecho = 'sem_resposta';
      silenciosos.push({ json: s });
      continue;
    }
    tipo = 'insiste'; status = 'aguardando'; quando = agora.plus({ minutes: intervalo }); insistencias = ins + 1;
  } else if (r.insistir === false) {
    tipo = 'aviso'; status = passo ? 'pendente' : 'enviado'; quando = passo ? proxima : q; insistencias = 0;
  } else {
    tipo = 'novo'; status = 'aguardando'; quando = agora.plus({ minutes: intervalo }); insistencias = 1;
  }
  // Contas a pagar falam com a voz do Dyno; os demais lembretes, com a Dina. Remédios saem numa mensagem própria.
  const voz = r.conta_id ? 'dyno' : 'dina';
  const numero = r.telefone || NUMERO_PADRAO;
  const k = numero + '|' + voz + '|' + nome + (rem ? '|rem' : '');
  const g = grupos[k] || (grupos[k] = { numero, voz, nome, rem, itens: [], apagar: [] });
  const atraso = agora.diff(q, 'minutes').minutes;
  g.itens.push({ id: r.id, tipo, conta: !!r.conta_id, texto: String(r.texto || ''), era: (tipo === 'novo' && atraso > 30) ? q.setZone(TZ).toFormat('dd/LL HH:mm') : '', status, quando: quando.toUTC().toISO(), insistencias, proxima: prox });
  // Insistência: apaga o aviso anterior sem resposta (se vários lembretes vieram na mesma mensagem, apaga uma vez só).
  if (r.status === 'aguardando' && r.msg_id && !g.apagar.some(a => a.id === String(r.msg_id))) g.apagar.push({ id: String(r.msg_id), jid: String(r.msg_jid || numero) });
}
function textoRemedio(g) {
  const n = g.nome, I = g.itens;
  if (I.length === 1) {
    const s = I[0];
    if (s.tipo === 'insiste') return '💊 ' + n + ', tomou o remédio? *' + l1(s.texto) + '*' + NL + 'Responda *sim* quando tomar, ou *adiar 15* que eu te lembro de novo.';
    if (s.tipo === 'aviso') return '💊 *' + n + ':* ' + s.texto;
    return '💊 *Hora do remédio, ' + n + ':* ' + s.texto + (s.era ? NL + '_(era para ' + s.era + ')_' : '') + NL + 'Já tomou? Responda *sim* (ou *tomei*), ou *adiar 15* que eu te lembro depois.';
  }
  const linha = s => '• ' + l1(s.texto) + (s.era ? ' _(era ' + s.era + ')_' : '');
  const novos = I.filter(s => s.tipo !== 'insiste'), insis = I.filter(s => s.tipo === 'insiste');
  const p = [];
  if (novos.length) p.push('💊 *Hora dos remédios, ' + n + ':*' + NL + novos.map(linha).join(NL));
  if (insis.length) p.push('💊 *' + (novos.length ? 'E ainda sem confirmação:' : n + ', ainda sem confirmação:') + '*' + NL + insis.map(linha).join(NL));
  p.push('Já tomou? Responda *sim* (vale para todos), ou *adiar 15* que eu te lembro depois.');
  return p.join(NL + NL);
}
function textoGrupo(g) {
  if (g.rem) return textoRemedio(g);
  const n = g.nome, I = g.itens;
  if (I.length === 1) {
    const s = I[0];
    if (s.tipo === 'insiste') return s.conta
      ? '🔔 ' + n + ', e aquela conta? ' + l1(s.texto).replace('💸 Vence HOJE: ', '') + NL + 'Já pagou? Responda *paguei* (ou mande o comprovante), ou *adiar 60* que eu te lembro depois.'
      : '🔔 ' + n + ', ainda não vi seu ok: *' + s.texto + '*' + NL + 'Já fez? Responda *ok*, ou *adiar 30* (minutos) que eu te lembro depois.';
    if (s.tipo === 'aviso') return '🔔 *' + n + ':* ' + s.texto;
    return '⏰ *Lembrete, ' + n + ':* ' + s.texto + (s.era ? NL + '_(era para ' + s.era + ')_' : '') + (s.conta ? '' : NL + 'Responda *ok* quando fizer, ou *adiar 30* (minutos) que eu te lembro depois.');
  }
  const linha = s => '• ' + l1(s.texto) + (s.era ? ' _(era ' + s.era + ')_' : '');
  const novos = I.filter(s => s.tipo === 'novo'), insis = I.filter(s => s.tipo === 'insiste'), avisos = I.filter(s => s.tipo === 'aviso');
  const p = [];
  if (novos.length) p.push((g.voz === 'dyno' ? '💸 *Contas, ' : '⏰ *Lembretes, ') + n + ':*' + NL + novos.map(linha).join(NL));
  if (insis.length) p.push('🔔 *' + (novos.length ? 'E ainda sem seu ok:' : n + ', ainda sem seu ok:') + '*' + NL + insis.map(linha).join(NL));
  if (avisos.length) p.push('🔔 *' + (p.length ? 'Avisos:' : 'Avisos, ' + n + ':') + '*' + NL + avisos.map(linha).join(NL));
  const precisaOk = novos.concat(insis);
  if (precisaOk.some(s => !s.conta)) p.push('Responda *ok* quando fizer (vale para todos), ou *adiar 30* que eu te lembro depois.');
  if (precisaOk.some(s => s.conta)) p.push('Já pagou? Responda *paguei* (ou mande o comprovante), ou *adiar 60* que eu te lembro depois.');
  return p.join(NL + NL);
}
const saida = Object.values(grupos).map(g => ({ json: { numero: g.numero, voz: g.voz, texto: textoGrupo(g), itens: g.itens.map(({ id, status, quando, insistencias, proxima }) => ({ id, status, quando, insistencias, proxima })), apagar: g.apagar } }));
return saida.concat(silenciosos.map(s => ({ json: { numero: '', voz: '', texto: '', itens: [s.json], apagar: [] } })));

const TZ = 'America/Sao_Paulo';
const NUMERO = '120363412854461070@g.us'; // grupo DM Assessor Pessoal
const linhas = n => $(n).all().map(i => i.json).filter(r => r && r.id !== undefined && r.id !== null);
const agora = DateTime.now().setZone(TZ).setLocale('pt-BR');
const fimHoje = agora.endOf('day');
const diaSemana = agora.weekday; // 1 = segunda ... 7 = domingo
const valeHoje = dias => {
  const d = String(dias || 'todos').toLowerCase();
  if (d === 'seg-sex') return diaSemana <= 5;
  if (d === 'fim-de-semana' || d === 'sab-dom') return diaSemana >= 6;
  if (d === 'todos') return true;
  const mapa = { seg: 1, ter: 2, qua: 3, qui: 4, sex: 5, sab: 6, dom: 7 };
  return d.split(/[,\s]+/).some(x => mapa[x.slice(0, 3)] === diaSemana);
};
const de = r => r.autor || 'Daniel';
// Só a família aparece no resumo do grupo; clientes do piloto nunca entram aqui.
const ORDEM_PESSOAS = ['Daniel', 'Quézia', 'Eliezer'];
const rotina = linhas('Rotina matinal').filter(r => valeHoje(r.dias));
const tarefas = linhas('Tarefas abertas (resumo)');
const lembretesHoje = linhas('Lembretes pendentes (resumo)')
  .map(r => ({ ...r, dt: DateTime.fromISO(String(r.quando)).setZone(TZ) }))
  .filter(r => r.dt <= fimHoje).sort((a, b) => a.dt - b.dt);
const pessoas = ORDEM_PESSOAS;

const partes = ['☀️ *Bom dia, grupo!* Não esqueçam de fazer seus lançamentos hoje, estou aqui para ajudá-los. — Dyno 🤖'];
for (const p of pessoas) {
  const itens = [];
  for (const r of rotina.filter(r => r.pessoa === p)) itens.push(r.mensagem);
  for (const l of lembretesHoje.filter(r => de(r) === p)) itens.push('⏰ ' + l.dt.toFormat('HH:mm') + ' ' + l.texto);
  const nTarefas = tarefas.filter(t => de(t) === p).length;
  if (nTarefas) itens.push('📋 ' + nTarefas + (nTarefas === 1 ? ' tarefa aberta' : ' tarefas abertas'));
  if (!itens.length) continue;
  partes.push('\n*' + p + ':* ' + itens.join('\n   '));
}

let dev = null;
try { dev = $('Devocional do dia').first().json; } catch (e) { dev = null; }
if (dev && dev.titulo) {
  let reflexao = '';
  try { const c = $('Reflexão do dia (IA)').first().json; reflexao = String((c.choices && c.choices[0] && c.choices[0].message && c.choices[0].message.content) || '').trim(); } catch (e) { reflexao = ''; }
  partes.push('\n📖 *Devocional do dia — Dia ' + dev.dia + '*\n_' + dev.titulo + '_\nLeitura base: ' + dev.referencia + (reflexao ? '\n\n' + reflexao : '') + '\n\nLeitura completa no devocional, página ' + dev.pagina + '. Bom tempo com Deus! 🙏');
}
return [{ json: { numero: NUMERO, texto: partes.join('\n') } }];

// Uma mensagem pode levar vários lembretes: grava cada um com o id da mensagem enviada.
const out = [];
$input.all().forEach((it, i) => {
  const g = $('Tem mensagem?').itemMatching(i).json;
  const k = it.json.key || {};
  for (const s of g.itens || []) out.push({ json: { id: s.id, body: { status: s.status, quando: s.quando, insistencias: s.insistencias, proxima: s.proxima || null, msg_id: k.id || null, msg_jid: k.remoteJid || null } } });
});
return out;
